entries[284941] = { ["name"] = "Klagelied der Gier", ["text"] = "100 Energie\nWirken in 2 sek.\nKanalisiert 10 Sek. lang ein Klagelied der Gier, das allen Spielercharakteren alle 2 Sek. 49069 Schattenschaden zufügt. Der Schaden erhöht sich jedes Mal, wenn Schaden verursacht wird.\n\nSobald das Klagelied der Gier abgeschlossen wurde, erhält Opulenz einen Stapel von 'Gier'." }
